# POST /api/sheets/{sheetId}/import-people — add a person per pasted line of name,grade,terms,contact,
# in order. Every line is checked first by the person form's rules (a name or contact repeated within
# the import is refused too): when any line is refused nothing is added. Responds with how many were added.
# A viewer may change nothing: refused before anything is read or written.
guard:
  class: net.officefloor.hq.app.setting.RefuseViewer
  next: validate
validate:
  class: net.officefloor.hq.app.person.ValidateImport
  next: create
create:
  class: net.officefloor.hq.app.person.ImportPeople
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithImport
# PUT /api/sheets/{sheetId}/people/{personId} — edit a person; refused like an add, and refused
# (409) when the body's version is not the stored one: someone else saved the person meanwhile.
# A viewer may change nothing: refused before anything is read or written.
guard:
  class: net.officefloor.hq.app.setting.RefuseViewer
  next: validate
validate:
  class: net.officefloor.hq.app.person.ValidatePerson
  next: before
before:
  class: net.officefloor.hq.app.rollup.TakeRollup
  govern: [ transaction ]
  next: load
load:
  class: net.officefloor.hq.app.person.LoadPerson
  govern: [ transaction ]
  next: apply
apply:
  class: net.officefloor.hq.app.person.ApplyPerson
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.person.SavePerson
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.person.RecordPersonEdited
  govern: [ transaction ]
  next: rollup
rollup:
  class: net.officefloor.hq.app.rollup.RecordRollup
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithPerson
=== ValidateImport
package net.officefloor.hq.app.person;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Splits the import into its lines (blank lines skipped) and checks each with the person form's own
 *  rules; a name or contact repeated within the import, or an import with no lines, is refused. */
public class ValidateImport {
    public void validate(@RequestBody ImportRequest request, Out<ImportLines> lines)
            throws InvalidPersonException {
        String text = request == null || request.text() == null ? "" : request.text();
        List<PersonRequest> checked = new ArrayList<>();
        Set<String> names = new HashSet<>();
        Set<String> contacts = new HashSet<>();
        for (String line : text.split("\\r?\\n")) {
            if (line.isBlank()) continue;
            String[] f = line.split(",", 4);
            PersonRequest person = PersonForm.check(new PersonRequest(f[0], f.length > 1 ? f[1] : "", null,
                    f.length > 2 ? f[2] : "", null, f.length > 3 ? f[3] : ""));
            if (!names.add(person.name().toLowerCase(Locale.ROOT))) {
                throw new InvalidPersonException("The name is repeated in the import: " + person.name());
            }
            if (person.contact() != null && !contacts.add(person.contact())) {
                throw new InvalidPersonException("The contact is repeated in the import: " + person.contact());
            }
            checked.add(person);
        }
        if (checked.isEmpty()) {
            throw new InvalidPersonException("Import at least one line of name,grade,terms,contact");
        }
        lines.set(new ImportLines(checked));
    }
}
