import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { useSubmitOnce } from '../../forms/useSubmitOnce';
import { importPeople, peopleKey } from './api';

/** A box that adds a person per pasted line of name,grade,terms,contact, and how many it added.
 *  The count is cleared while it runs; a refused import adds nothing and shows an error. */
export function ImportPeople({ sheetId, user }: { sheetId: string; user: string }) {
  const queryClient = useQueryClient();
  const [text, setText] = useState('');
  const submitOnce = useSubmitOnce();

  const imported = useMutation({
    mutationFn: (input: string) => importPeople(sheetId, user, input),
    // Not awaited: the count shows as soon as the import is done, never after its new rows.
    onSuccess: () => { void queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) }); },
  });

  return (
    <form
      onSubmit={(e) => {
        e.preventDefault();
        const input = text;
        submitOnce(() => {
          imported.reset();
          return imported.mutateAsync(input);
        });
      }}
    >
      <label>
        Import people (name,grade,terms,contact per line; terms and contact may be left out){' '}
        <textarea data-testid="import-people" rows={3} value={text}
          onChange={(e) => {
            setText(e.target.value);
            if (imported.isError) imported.reset();
          }} />
      </label>{' '}
      <button type="submit" data-testid="import-submit" disabled={imported.isPending}>
        Import people
      </button>
      {imported.isSuccess && (
        <>
          {' '}Added <span data-testid="import-added">{imported.data.added}</span>
        </>
      )}
      {imported.isError && (
        <span data-testid="import-error">Every line needs a name and contact (if any) not already in use nor repeated, a grade of A, B or C, and terms (if any) a whole number of days: nothing was imported.</span>
      )}
    </form>
  );
}
/** Add a person; refused (rejects) when the name is empty or already in use on the sheet. */
export function addPerson(sheetId: string, by: string, input: PersonInput): Promise<Person> {
  return postJson<Person>(`${base(sheetId)}?by=${encodeURIComponent(by)}`, input);
}

/** How many people an import added. */
export type ImportResult = { added: number };

/** Add a person per line of name,grade,terms,contact (terms and contact may be absent or blank), in
 *  order, each as the person form adds them; refused (rejects), adding nothing, when any line would be
 *  refused by the person form or repeats a name or contact of another line. */
export function importPeople(sheetId: string, by: string, text: string): Promise<ImportResult> {
  return postJson<ImportResult>(`/api/sheets/${encodeURIComponent(sheetId)}/import-people?by=${encodeURIComponent(by)}`, { text });
}

